def step(context):
    world = context['inputs']['observations'][0]['payload']
    cost = context['parameters']['publication_cost']
    offers = []
    for conf in world['conferences']['conferences']:
        for paper in conf['submitted_papers']:
            reviews = conf['reviews'].get(paper['id'], [])
            mean_score = sum(review['overall_score'] for review in reviews) / len(reviews) if reviews else 0.0
            offers.append({'paper_id': paper['id'], 'conference_id': conf['conference_id'], 'review_mean': mean_score, 'loss_increment': cost - mean_score})
    packet = {'payload': {'year': context['period'], 'offers': offers}, 'actor_ids': [], 'artifact_ids': []}
    return {'outputs': {'offers': [packet]}, 'state': {}}
